def calculate_daily_returns(self, ticker: str, start_date: str, end_date: str) -> pd.Series:
    """Calculate daily returns for a ticker."""
    data = self.get_price_data(ticker, start_date, end_date)

    if data is None or data.empty:
        logger.warning(f"{ticker}: No price data")
        return None

    # Handle yfinance MultiIndex columns (when downloading tickers)
    if isinstance(data.columns, pd.MultiIndex):
        # yfinance returns MultiIndex with ('Price', 'Ticker')
        # Try 'Close' first (standard), then 'Adj Close' (older versions)
        try:
            close_price = data[('Close', ticker)]
        except KeyError:
            try:
                close_price = data[('Adj Close', ticker)]
            except KeyError:
                logger.warning(f"{ticker}: 'Close' column not found in {data.columns.tolist()}")
                return None
    else:
        # Single ticker, regular columns
        try:
            close_price = data['Close']
        except KeyError:
            close_price = data['Adj Close']

    # Calculate daily returns
    daily_returns = close_price.pct_change().dropna()

    if len(daily_returns) == 0:
        logger.warning(f"{ticker}: No returns calculated")
        return None

    return daily_returns
